1	import React from 'react';
2	import { Box } from '@salesforce/retail-react-app/app/components/shared/ui';
3	import type { BoxProps } from '@chakra-ui/layout';
4	
5	type BoxedProp = boolean | 'desktop';
6	
7	type PageContainerProps = BoxProps & {
8	  /**
9	   * Controls horizontal containment:
10	   *   true       — constrained (maxWidth + padding) on all breakpoints
11	   *   "desktop"  — full-width on mobile, constrained from lg upward
12	   *   false      — full-width everywhere (default)
13	   */
14	  boxed?: BoxedProp;
15	};
16	
17	const PageContainer = ({ boxed, children, ...rest }: PageContainerProps) => {
18	  const maxWidthValue = !boxed
19	    ? undefined
20	    : boxed === 'desktop'
21	    ? { base: '100%', lg: 'container.xxxl' }
22	    : 'container.xxxl';
23	
24	  const paddingXValue = !boxed ? undefined : boxed === 'desktop' ? { base: 0, lg: 6, xl: 8 } : [4, 4, 6, 6, 8];
25	
26	  // 'auto' (not '100%') when unboxed — a fixed width stops a negative marginX from actually
27	  // growing the box, only letting it shift position (SFCC-731 full-bleed bug fix).
28	  const widthValue = boxed ? '100%' : 'auto';
29	
30	  return (
31	    <Box
32	      width={widthValue}
33	      maxWidth={maxWidthValue}
34	      marginX={boxed ? 'auto' : undefined}
35	      paddingX={paddingXValue}
36	      {...rest}
37	    >
38	      {children}
39	    </Box>
40	  );
41	};
42	
43	export default PageContainer;
