2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { useHistory } from 'react-router-dom';
4	import { defineMessages, useIntl } from 'react-intl';
5	import { ZimmColourSwatch } from '../../atoms/zimmColourSwatch';
6	import { ChevronLeftIcon, ChevronRightIcon } from '../../../icons';
7	import { SWATCHES_PER_PAGE } from './zimmColourSwatchGroupShared';
8	
9	const messages = defineMessages({
10	  groupLabel: { id: 'colour_swatches.group.label', defaultMessage: 'Colour' },
11	  label: { id: 'colour_swatches.label', defaultMessage: 'Colour:' },
12	  paginationGroupLabel: { id: 'colour_swatches.pagination.group_label', defaultMessage: 'Colour swatch pages' },
13	  next: { id: 'colour_swatches.pagination.next', defaultMessage: 'Next colours' },
14	  previous: { id: 'colour_swatches.pagination.previous', defaultMessage: 'Previous colours' },
15	});
16	
17	const ZIMM_COLOUR_SWATCH_GROUP_RECIPE = 'ZimmColourSwatchGroup';
18	
19	/** One selectable colour variation as the molecule expects it — pre-mapped from the raw SFCC shape. */
20	export type ZimmColourSwatchValue = {
21	  value: string;
22	  name: string;
23	  /** Resolved swatch fill image URL. Absence means the colour has no swatch image and is withheld. */
24	  imageUrl?: string;
25	  /** Router destination URL for this colour. Absent on the quick-view modal path. */
26	  href?: string;
27	  /** Mirrors SFCC's `orderable` flag. Unavailable colours are withheld (not shown as disabled). */
28	  orderable?: boolean;
29	  /**
30	   * When true, clicking navigates via a native anchor (full page reload) rather than a router
31	   * Link. Set for related-colour swatches (SFCC-708) that link to a different master product.
32	   */
33	  forceReload?: boolean;
34	};
35	
36	type ZimmColourSwatchGroupProps = {
37	  values: ZimmColourSwatchValue[];
38	  /** Currently selected colour value (from URL / variation params). */
39	  selectedValue?: string;
40	  /**
41	   * Display label for the colour group. Defaults to the i18n "Colour" value.
42	   * Pass an explicit value when the SFCC attribute display name differs from the default.
43	   */
44	  label?: string;
45	  /**
46	   * When `label` is a field name (e.g. "Colour"), the group appends ":" itself — the default.
47	   * Set false for a lead-in phrase that already reads correctly on its own (e.g. "Also
48	   * available in"), where an appended colon would be wrong.
49	   */
50	  appendColon?: boolean;
51	  /**
52	   * Selection callback for the linkless path (no `href` on values). Called on click and
53	   * arrow-key navigation. Not needed on the PDP, where each value carries an `href` and
54	   * selection is handled by router navigation.
55	   */
56	  onSelect?: (value: string) => void;
57	  /**
58	   * Tile shape for every swatch in the group. Defaults to `'square'` (main PDP) — zero
59	   * behaviour change for every existing caller. `'circle'` is the SFCC-731 gallery overlay's
60	   * 20px, underline-selected tile.
61	   */
62	  variant?: 'square' | 'circle';
63	};
64	
65	/**
66	 * Molecule — the full colour-swatch group: label row (name + pagination arrows), and a
67	 * `[role=radiogroup]` swatch strip of `ZimmColourSwatch` atoms with roving tabindex and
68	 * keyboard navigation.
69	 *
70	 * When only one offered colour exists, the label and name render but the swatch row is
71	 * suppressed (nothing to choose between). Colours without a swatch image or marked
72	 * non-orderable are withheld entirely.
73	 */
74	export const ZimmColourSwatchGroup = ({
75	  values,
76	  selectedValue,
77	  label,
78	  appendColon = true,
79	  onSelect,
80	  variant = 'square',
81	}: ZimmColourSwatchGroupProps) => {
82	  const intl = useIntl();
83	  const groupLabel = label ?? intl.formatMessage(messages.groupLabel);
84	  const labelText = label != null ? (appendColon ? `${label}:` : label) : intl.formatMessage(messages.label);
85	
86	  // Filter to only offered (orderable + swatch image populated) colours.
87	  const offered = values.filter((v) => Boolean(v.imageUrl) && v.orderable !== false);
88	
89	  const isPaginated = offered.length > SWATCHES_PER_PAGE;
90	  const pageCount = Math.ceil(offered.length / SWATCHES_PER_PAGE);
91	
92	  const [page, setPage] = useState(0);
93	
94	  // Auto-advance to the page containing the pre-selected value on mount or when selectedValue
95	  // changes (e.g. browser back/forward lands on a colour that is off page 0).
96	  // When selectedValue is absent or not in the offered set, clamp to the highest valid page so
97	  // all remaining swatches stay visible after the offered set shrinks (e.g. a colour becomes
98	  // unavailable while the user is on a later page).
99	  useEffect(() => {
100	    const idx = offered.findIndex((v) => v.value === selectedValue);
101	    if (idx >= 0) {
102	      setPage(Math.floor(idx / SWATCHES_PER_PAGE));
103	    } else {
104	      const pc = Math.ceil(offered.length / SWATCHES_PER_PAGE);
105	      setPage((p) => Math.min(p, Math.max(0, pc - 1)));
106	    }
107	    // offered.length captures filter changes; selectedValue tracks URL/prop changes.
108	  }, [selectedValue, offered.length]);
109	
110	  // Roving tabindex: the focused atom is either the selected one or index 0 (no selection).
111	  const selectedIndex = offered.findIndex((v) => v.value === selectedValue);
112	  const tabFocusIndex = selectedIndex >= 0 ? selectedIndex : 0;
113	
114	  // True when the globally-selected swatch falls on the current visual page.
115	  const isTabFocusOnPage = Math.floor(tabFocusIndex / SWATCHES_PER_PAGE) === page;
116	
117	  // Focus management after keyboard navigation. After history.push updates the URL and React
118	  // re-renders with a new selectedValue, focus the newly-focusable atom imperatively so the
119	  // shopper doesn't have to re-tab to continue arrow-key navigation.
120	  const radioGroupRef = useRef<HTMLDivElement>(null);
121	  const hasNavigated = useRef(false);
122	
123	  useEffect(() => {
124	    if (hasNavigated.current) {
125	      const focusable = radioGroupRef.current?.querySelector('[tabindex="0"]') as HTMLElement | null;
126	      focusable?.focus();
127	      hasNavigated.current = false;
128	    }
129	  }, [selectedValue]);
130	
131	  const history = useHistory();
132	
133	  const handleSwatchesKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
134	    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
135	    e.preventDefault();
136	
137	    // Derive current index from the focused element's data-swatch-value — a unique value
138	    // identity that survives duplicate display names (e.g. two shades both named "Bay Blue").
139	    const focusedValue = (document.activeElement as HTMLElement | null)
140	      ?.closest('[data-swatch-value]')
141	      ?.getAttribute('data-swatch-value');
142	    const focusedIndex = focusedValue ? offered.findIndex((v) => v.value === focusedValue) : -1;
143	    const currentIndex = focusedIndex >= 0 ? focusedIndex : tabFocusIndex;
144	
145	    const isForward = e.key === 'ArrowRight' || e.key === 'ArrowDown';
146	    const nextIndex = isForward
147	      ? (currentIndex + 1) % offered.length
148	      : (currentIndex - 1 + offered.length) % offered.length;
149	
150	    const next = offered[nextIndex];
151	    const nextPage = Math.floor(nextIndex / SWATCHES_PER_PAGE);
152	
153	    setPage(nextPage);
154	    hasNavigated.current = true;
155	
156	    if (next.href) {
157	      if (next.forceReload) {
158	        window.location.href = next.href;
159	      } else {
160	        history.push(next.href);
161	      }
162	    } else {
163	      onSelect?.(next.value);
164	    }
165	  };
166	
167	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_GROUP_RECIPE, { isPaginated, variant });
168	
169	  const selectedName = offered.find((v) => v.value === selectedValue)?.name ?? offered[0]?.name;
170	
171	  // No offered colours at all (every value failed the imageUrl/orderable filter) — suppress
172	  // the entire group including the label so a bare "Colour:" never appears on the PDP.
173	  if (offered.length === 0) return null;
174	
175	  return (
176	    <chakra.div __css={styles.root}>
177	      <chakra.div __css={styles.label}>
178	        <chakra.span textStyle="caption">{labelText}</chakra.span>
179	        {appendColon && selectedName && (
180	          <chakra.span data-testid="pdp-colour-selected-name" __css={styles.labelName}>
181	            {selectedName}
182	          </chakra.span>
183	        )}
184	        {isPaginated && (
185	          <chakra.div __css={styles.pagination} aria-label={intl.formatMessage(messages.paginationGroupLabel)}>
186	            <chakra.button
187	              as="button"
188	              __css={styles.pageButton}
189	              aria-label={intl.formatMessage(messages.previous)}
190	              disabled={page === 0}
191	              onClick={() => setPage((p) => p - 1)}
192	            >
193	              <ChevronLeftIcon aria-hidden boxSize="var(--zimm-scale-m)" />
194	            </chakra.button>
195	            <chakra.button
196	              as="button"
197	              __css={styles.pageButton}
198	              aria-label={intl.formatMessage(messages.next)}
199	              disabled={page === pageCount - 1}
200	              onClick={() => setPage((p) => p + 1)}
201	            >
202	              <ChevronRightIcon aria-hidden boxSize="var(--zimm-scale-m)" />
203	            </chakra.button>
204	          </chakra.div>
205	        )}
206	      </chakra.div>
207	
208	      {offered.length > 1 && (
209	        <chakra.div
210	          role="radiogroup"
211	          aria-label={groupLabel}
212	          ref={radioGroupRef}
213	          __css={styles.swatches}
214	          onKeyDown={handleSwatchesKeyDown}
215	        >
216	          {offered.map((v, i) => {
217	            const isOnPage = Math.floor(i / SWATCHES_PER_PAGE) === page;
218	            // Off-page swatches are always removed from the tab order (tabIndex="-1"), even
219	            // when they're the globally-selected colour, so Tab focus never lands on a
220	            // visually-hidden element. When the selected swatch is off-page (the user manually
221	            // paged without changing colour), the first on-page swatch becomes the tab stop.
222	            const isFocusable = isOnPage && (isTabFocusOnPage ? i === tabFocusIndex : i === page * SWATCHES_PER_PAGE);
223	
224	            return (
225	              // All swatches are always in the DOM so screen readers can navigate the full set
226	              // and aria-posinset/aria-setsize reports the correct total count ("N of M" where
227	              // M = all offered colours, not just the current page). Off-page swatches are
228	              // absolutely positioned — removed from the flex flow so they don't widen the row —
229	              // and clip-path'd to a 0×0 visible area so they are invisible on screen while
230	              // remaining in the accessibility tree.
231	              <chakra.span
232	                key={v.value}
233	                data-swatch-value={v.value}
234	                style={isOnPage ? undefined : { position: 'absolute', clipPath: 'inset(50%)' }}
235	              >
236	                <ZimmColourSwatch
237	                  name={v.name}
238	                  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
239	                  imageUrl={v.imageUrl!}
240	                  href={v.href}
241	                  forceReload={v.forceReload}
242	                  onClick={onSelect ? () => onSelect(v.value) : undefined}
243	                  isSelected={v.value === selectedValue}
244	                  isFocusable={isFocusable}
245	                  posInSet={i + 1}
246	                  setSize={offered.length}
247	                  variant={variant}
248	                />
249	              </chakra.span>
250	            );
251	          })}
252	        </chakra.div>
253	      )}
254	    </chakra.div>
255	  );
256	};
257	
258	export default ZimmColourSwatchGroup;
